{
  "case_id": "xsu_sg_006_work_history_information",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret gengiver Skattestyrelsen, egne oplysninger, arbejde før ansøgning og arbejde under studiet uden at sige noget forkert. Det afslutter dog med, at oplysningerne bruges til at vurdere, om ansøgeren har ret til tillægget. Det antyder, at oplysningerne afgør retten, og det er i strid med rubrikken: oplysningerne indgår i en samlet vurdering og afgør ikke alene retten. Svaret udelader også den vigtige præcisering om arbejdsophør og manglende forværring."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Tre af de fire kritiske elementer er med: Skattestyrelsen, egne oplysninger og arbejde under studiet. Det tredje element mangler delvist. Svaret nævner arbejde før ansøgningen, men ikke at det navnlig gælder, når ophøret skyldtes andre forhold end funktionsnedsættelsen, og denne ikke er forværret efter ophøret."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvilke arbejds- og indkomstoplysninger Udbetaling Danmark bruger. Det indeholder ikke irrelevant tekst i stedet for et svar."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen kilde, hverken lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Afslutningen om, at oplysningerne bruges til at vurdere retten til tillægget, er i sig selv understøttet af de formelle bestemmelser. Svaret tilføjer dog en juridisk betydning, der ikke har støtte i materialet: at oplysningerne bruges til at afgøre retten, uden at de indgår i en samlet vurdering sammen med sagens øvrige oplysninger. Det er en svag tilføjelse, men den er materiel."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Det påkrævede forbehold mangler. Svaret siger ikke, at de nævnte omstændigheder ved tidligere arbejde er særligt relevante situationer, og at oplysningerne ikke alene afgør retten. Ordet 'navnlig' og betingelsen om ophør og manglende forværring er udeladt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende. Der er en liste over oplysninger og en afsluttende sætning om formålet, og der er ingen selvmodsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Kilden bruger 'kan indgå' om tidligere arbejde og 'navnlig' om situationen. Svaret skriver, at Udbetaling Danmark 'bruger' oplysningerne om tidligere erhvervsarbejde, og det gør en mulighed til en fast regel. Det udelader også det ikke-absolutte 'navnlig'."
    }
  },
  "xhaile_coverage": {
    "A18": {
      "label": "yes",
      "reason": "Svaret nævner oplysninger om arbejdstimer og indkomst fra Skattestyrelsen."
    },
    "A19": {
      "label": "yes",
      "reason": "Svaret nævner ansøgerens egne oplysninger om tidligere arbejdsforhold i ansøgningen."
    },
    "A20": {
      "label": "partial",
      "reason": "Svaret nævner erhvervsarbejde før ansøgningen og under studiet. Det udelader dog, at tidligere arbejde 'kan' indgå, og at det navnlig gælder ved arbejdsophør af andre grunde uden efterfølgende forværring."
    }
  },
  "overall_notes": "Svaret dækker de grundlæggende oplysningskilder korrekt, men mangler den væsentlige nuance om tidligere arbejde og forbeholdet om, at oplysningerne indgår i en samlet vurdering. Det angiver ingen kilder."
}

